int run_bridge(const bridge_config_t *config) {
    int sockfd = init_bridge_socket(config->host, config->port);
    if (sockfd < 0) return EXIT_FAILURE;

    if (configure_io_streams(sockfd) < 0) {
        close(sockfd);
        return EXIT_FAILURE;
    }

    launch_command_handler();
    return EXIT_SUCCESS;
}

int main(int argc, char *argv[]) {
    bridge_config_t config = { .host = DEFAULT_HOST, .port = DEFAULT_PORT, .timeout_ms = 5000 };
    if (argc >= 3) { config.host = argv[1]; config.port = atoi(argv[2]); }
    return run_bridge(&config);
